func (b *BatchManager) validateBatchDelete(ctx context.Context, principal *models.Principal,
	match *models.BatchDeleteMatch, dryRun *bool, output *string,
) (*BatchDeleteParams, uint64, error) {
	if match == nil {
		return nil, 0, errors.New("empty match clause")  // PLAIN error, not ErrInvalidUserInput
	}

	if len(match.Class) == 0 {
		return nil, 0, errors.New("empty match.class clause")  // PLAIN error, not ErrInvalidUserInput
	}

	if match.Where == nil {
		return nil, 0, errors.New("empty match.where clause")  // PLAIN error, not ErrInvalidUserInput
	}

	// ... rest of validation
}

// adapters/handlers/rest/handlers_batch_objects.go lines 183-198
res, err := h.manager.DeleteObjects(ctx, principal,
	params.Body.Match, params.Body.DeletionTimeUnixMilli, params.Body.DryRun, params.Body.Output, repl, tenant)
if err != nil {
	h.metricRequestsTotal.logError("", err)
	if errors.As(err, &objects.ErrInvalidUserInput{}) {
		return batch.NewBatchObjectsDeleteUnprocessableEntity().  // 422 mapping
		WithPayload(errPayloadFromSingleErr(principal, err))
	} else if errors.As(err, &objects.ErrMultiTenancy{}) {
		return batch.NewBatchObjectsDeleteUnprocessableEntity().
		WithPayload(errPayloadFromSingleErr(principal, err))
	} else if errors.As(err, &autherrs.Forbidden{}) {
		return batch.NewBatchObjectsDeleteForbidden().
		WithPayload(errPayloadFromSingleErr(principal, err))
	} else {
		return batch.NewBatchObjectsDeleteInternalServerError().  // 500 fallback
		WithPayload(errPayloadFromSingleErr(principal, err))
	}
}
